(function(){'use strict';const VERSION='20260821-1';const item={id:VERSION,type:'update',version:VERSION,date:'2026-08-21',title:'人格引擎 2.0 與主動私聊',summary:'角色現在會依關係、事件與個性主動私聊；新增人格校準與可選 OOC 二次審稿。',items:['主動聊天不再隨機抽兩名角色，而會依關係親密度、近期共同事件、最近動態、沉默時間與角色主動性決定誰會主動找誰。','新增角色「人格校準 2.0」：可設定主動聯絡、訊息長度、情緒外露、溫柔、衝突、直白等傾向。','角色編輯可填「這才是他會說的話」與「他絕對不會這樣說」，作為 AI 語氣正反例。','聊天允許不對稱：寡言角色可以短回、拒絕延伸、轉移話題，不再強迫兩人平均發言。','動態或事件發生後，若關係與性格合理，角色可能稍後轉到私聊繼續互動。','新增可關閉的 OOC 二次審稿；開啟時聊天會多用一次 AI 請求，專門檢查是否把角色平均化成通用溫柔口吻。','角色缺點、嘴硬、冷淡、病嬌、低共情、偏執等設定被提升為硬約束，不再被默認的健康溝通模板覆蓋。']};const original=window.fetch.bind(window);window.fetch=async function(input,init){const response=await original(input,init);try{const url=typeof input==='string'?input:input?.url||'';if(!/announcements\.json(?:[?#]|$)/.test(url)||!response.ok)return response;const data=await response.clone().json();if(!data||!Array.isArray(data.announcements)||data.announcements.some(x=>x?.id===VERSION))return response;return new Response(JSON.stringify({...data,latest:VERSION,announcements:[item,...data.announcements]}),{status:response.status,statusText:response.statusText,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'}})}catch(_){return response}};window.OCLifeReleaseNotice20260821={version:VERSION};})();